update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance conditionnelle","mecanisme":"On ne change plus un composant parce que le calendrier le dit, mais parce que l''état réel le demande. Ci-dessous : la définition, les technologies de surveillance, la méthode. Puis qui relève, et qui interprète.","cta":"Lancer mon diagnostic gratuit","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option."},{"type":"chiffres","chiffres":[{"valeur":"Préventive.","libelle":"La conditionnelle est une branche du préventif, pas une alternative."},{"valeur":"Surveillance.","libelle":"En continu ou par rondes périodiques, avec des mesures physiques réelles."},{"valeur":"Actions qui en découlent.","libelle":"Sans décision derrière la donnée, vous avez acheté des capteurs, pas une démarche."},{"valeur":"L''analyse vibratoire détecte l''usure mécanique des semaines avant la casse.","libelle":"Balourd, désalignement, jeu, roulement écaillé, denture usée : chaque défaut a sa signature dans le spectre","detail":"Le relevé se fait sans contact et sans arrêt de production, avec les classes de sévérité de type ISO 10816 en référence."},{"valeur":"La thermographie infrarouge voit ce que personne ne peut toucher.","libelle":"Une connexion électrique desserrée chauffe avant de fondre, un roulement en fin de vie monte en chaleur avant de gripper","detail":"Mesure sans contact, en marche, sur du matériel sous tension."},{"valeur":"L''analyse d''huile lit l''usure interne sans ouvrir la machine.","libelle":"Quelques centilitres suffisent pour doser particules métalliques, eau, viscosité, acidité","detail":"Le meilleur moyen de suivre un réducteur, une centrale hydraulique ou un compresseur."},{"valeur":"Le contrôle électrique transforme vos automates en capteurs gratuits.","libelle":"Intensité moteur, temps de cycle, pression, débit, code défaut récurrent : ces données existent déjà chez vous."},{"valeur":"Les ultrasons chassent ce qui fuit.","libelle":"Air comprimé, défauts de lubrification, décharges partielles, pertes de pression sur les circuits."},{"valeur":"La ronde visuelle reste imbattable.","libelle":"Bien tenue, guidée par une fiche et tracée, elle repère ce qu''aucun capteur ne mesure."},{"valeur":"10 %","libelle":"des candidats retenus, l''interprétation d''un spectre vibratoire s''évalue en entretien"},{"valeur":"8","libelle":"domaines techniques couverts par une seule équipe, de la mécanique à la robotique"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, des campagnes partout en France"}],"reponse":[{"texte":"En anglais, condition based maintenance, ou CBM. Trois mots comptent dans cette phrase."}]},{"type":"probleme","punchline":"Vous jetez des roulements qui avaient encore six mois de vie. Et le mois suivant, un moteur lâche sans prévenir.","puces":[{"accroche":"La compétence d''interprétation est rare.","texte":"Lire un spectre vibratoire est un métier. Peu de sites ont quelqu''un dont c''est réellement le poste, et le marché ne le fournit pas vite."},{"accroche":"La campagne saute à la première urgence.","texte":"Une ronde de relevés qui ne figure pas au planning au même titre que les travaux préventifs disparaît en trois mois."},{"accroche":"Un spectre mal lu produit une fausse alarme.","texte":"Et une fausse alarme de trop décrédibilise tout le dispositif auprès de la production."},{"accroche":"Le programme se périme en silence.","texte":"Sans revue régulière des seuils et des points de contrôle, il s''éteint doucement, en dix-huit mois, sans que personne le décide."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Le diagnostic de votre parc et la hiérarchisation des actifs","texte":"nous reprenons votre historique de pannes et identifions où la surveillance sera rentable."},"benefice":"Une liste priorisée, pas une étude de cinquante pages. Vous savez par quoi commencer."},{"prestation":{"accroche":"Les campagnes de mesures périodiques","texte":"analyse vibratoire, thermographie infrarouge, prélèvements d''huile, contrôles électriques."},"benefice":"Vous obtenez la compétence d''interprétation sans avoir à la recruter."},{"prestation":{"accroche":"Un rapport lisible en une page","texte":"ce qui va, ce qui dérive, ce qui doit être traité et dans quel ordre."},"benefice":"Un compte rendu que le responsable de production lit en trois minutes se transforme en décisions."},{"prestation":{"accroche":"La mise en place du programme","texte":"points de contrôle, référence à froid, limites d''alarme, procédures de ronde, branchement dans votre GMAO."},"benefice":"Le dispositif tient dans la durée parce qu''il est inscrit dans votre organisation, pas à côté."},{"prestation":{"accroche":"L''exécution des travaux déclenchés par le relevé","texte":"remplacement de roulement, réalignement, reprise de connexion, remise en état hydraulique."},"benefice":"Le seuil franchi devient une machine réparée, pas une alerte de plus."},{"prestation":{"accroche":"Un technicien intégré sur site","texte":"pour les usines qui veulent une présence continue, avec les habilitations et autorisations de zone nécessaires."},"benefice":"La surveillance ne dépend plus de la disponibilité d''un prestataire extérieur."},{"prestation":{"accroche":"L''astreinte 24/24 et 7/7 en option","texte":", parce qu''aucune surveillance ne capte toutes les défaillances."},"benefice":"La couverture hors heures ouvrées reste assurée, même avec un bon programme."}],"prose":[{"texte":"Pour industrialiser la démarche avec un programme suivi et une priorité d''intervention, voir le [contrat de maintenance Zéro arrêt](/offres/zero-arret/). Pour une panne en cours, voir le [dépannage industriel](/offres/depannage-industriel/). Migen est une [entreprise de maintenance industrielle](/offres/) présente partout en France."}]},{"type":"deroule","etapes":[{"titre":"Inventorier les actifs et hiérarchiser la criticité.","texte":"Impact d''un arrêt sur la production, sécurité des personnes, coût de la remise en état, délai d''approvisionnement des pièces. Tout ne mérite pas d''être surveillé."},{"titre":"Choisir les modes de défaillance et la technique adaptée.","texte":"Vibration pour les tournantes, thermographie pour l''électrique, analyse d''huile pour les carters, paramètres process pour le reste."},{"titre":"Définir les points de mesure et la périodicité.","texte":"Un point mal placé ne détecte rien. Trop lâche, la périodicité laisse passer la dégradation. Trop serrée, elle épuise le personnel."},{"titre":"Établir la référence à froid.","texte":"La première campagne fixe la signature de chaque équipement en bon état. Sans ce point zéro, aucune comparaison n''est possible."},{"titre":"Fixer les limites d''alarme et le seuil critique.","texte":"Deux niveaux au minimum : une limite de vigilance qui déclenche un suivi rapproché, un seuil critique qui déclenche l''intervention."},{"titre":"Brancher la GMAO et boucler.","texte":"Chaque dépassement crée une demande de travail, avec un responsable nommé et une date. Après l''intervention, on compare l''état constaté à la prévision et on corrige les seuils."}]},{"type":"garanties","puces":[{"accroche":"Un seuil franchi, c''est une action.","texte":"Pas un débat, pas une réunion. L''action peut être un contrôle renforcé, une commande de pièce ou une intervention planifiée, mais elle porte un nom de responsable et une date."},{"accroche":"Une donnée comparable d''une campagne à l''autre.","texte":"Repérage physique durable des points de contrôle, même méthode de relevé, même technicien quand c''est possible. Un point mal repéré produit une valeur fausse."},{"accroche":"Un contact unique qui suit votre dossier","texte":"et qui vous rend compte des actions menées. Chaque technicien mobilisé a passé une évaluation technique et comportementale en entretien, seuls 10 % des candidats sont retenus."}]},{"type":"cta","question":"Besoin de savoir quelles machines méritent une ronde mensuelle, et lesquelles peuvent rester au calendrier ?","bouton":"Lancer mon diagnostic gratuit","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Maintenance préventive et curative d''une fonderie et d''un usinage, automobile","texte":"tenue 7 jours sur 7, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Reprise complète de la maintenance préventive annuelle de deux sites, e-commerce","texte":"six techniciens en permanence","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Maintien d''un parc machines, équipementier automobile","texte":"un technicien de maintenance dédié, intégré aux équipes en 2025","lienLibelle":"Étude de cas AUTOLIV : maintien d''un site","lienHref":"/preuves/autoliv/"},{"titre":"Renfort de 1 à 3 techniciens sur des sites de production, chauffage et sanitaire","texte":"depuis octobre 2024","lienLibelle":"Étude de cas GROUPE ATLANTIC : renfort d''équipes","lienHref":"/preuves/groupe-atlantic/"},{"titre":"Deux techniciens intégrés en 3x8 sur les lignes liquides et poudre, agroalimentaire","texte":"site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"}]},{"type":"objections","questions":[{"question":"Quelle différence avec la maintenance préventive systématique ?","reponse":"La systématique déclenche l''opération sur un calendrier fixe ou un compteur d''heures, que la pièce soit usée ou non. La conditionnelle déclenche sur une mesure d''état. Les deux sont des formes de préventif et cohabitent très bien dans un même plan."},{"question":"Ce n''est pas la même chose que la prédictive ?","reponse":"Non. La conditionnelle compare une mesure à un seuil, ici et maintenant. La prédictive projette une date de défaillance à partir de tendances et de modèles. La conditionnelle est le socle : sans mesures fiables, aucun modèle prédictif ne tient."},{"question":"Faut-il obligatoirement des capteurs fixes et une GMAO ?","reponse":"Non. Beaucoup de sites démarrent avec un collecteur portable, une ronde mensuelle et un tableau de suivi rigoureux. Les capteurs fixes se justifient sur les machines critiques ou difficiles d''accès. L''outil logiciel vient quand le volume de données le rend nécessaire."},{"question":"Qui interprète les mesures si nous n''avons pas la compétence en interne ?","reponse":"Nous. Nos techniciens réalisent la campagne, analysent les relevés et vous remettent un rapport avec les actions à mener et leur priorité. Nous formons aussi votre personnel pour reprendre la main progressivement, si c''est votre projet."},{"question":"Combien ça coûte, et au bout de combien de temps ça paie ?","reponse":"Le chiffrage se fait sur devis, selon le nombre d''actifs suivis et la périodicité. Les premières anomalies apparaissent souvent dès la campagne de référence, parce qu''elle révèle des défauts existants. Le gain de fond se mesure sur un cycle complet d''exploitation."},{"question":"Par quel équipement commencer ?","reponse":"Par celui dont l''arrêt coûte le plus cher à la production et dont la remise en état est la plus longue. Un seul actif critique bien suivi vaut mieux qu''un déploiement général mal tenu. C''est le premier arbitrage du diagnostic."}]},{"type":"ctaFinal","question":"Besoin d''arrêter de jeter des pièces encore bonnes, et de voir venir celles qui lâchent ?","bouton":"Lancer mon diagnostic gratuit","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."}]}'::jsonb where path = '/expertises/types-de-maintenance/maintenance-conditionnelle/';
